            <select id="bf-active" class="form-input">
              <option value="1" ${(Qe==null?void 0:Qe.active)!==!1?"selected":""}>Activa</option>
              <option value="0" ${(Qe==null?void 0:Qe.active)===!1?"selected":""}>Inactiva</option>
            </select>
